package com.studentgrade.service;

import com.studentgrade.dto.AuthDtos.*; import com.studentgrade.entity.*; import com.studentgrade.repository.*; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import java.util.*;

@Service public class ResultService { private final ResultRepository results; private final StudentRepository students; private final GradeCalculationService calc;
 public ResultService(ResultRepository results,StudentRepository students,GradeCalculationService calc){this.results=results;this.students=students;this.calc=calc;}
 public ResultResponse calculate(String roll,ResultRequest request){Student s=student(roll); if(request.subjects().stream().anyMatch(x->x.marks()==null||x.marks()<0||x.marks()>100))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Marks must be between 0 and 100"); int total=calc.total(request.subjects()), max=request.subjects().size()*100; double pct=Math.round(total*10000.0/max)/100.0; Result r=new Result();r.setStudent(s);r.setTotalMarks(total);r.setMaximumMarks(max);r.setAveragePercentage(pct);r.setGrade(calc.grade(pct));r.setFeedback(calc.feedback(pct));for(SubjectRequest x:request.subjects()){SubjectMark m=new SubjectMark();m.setResult(r);m.setSubjectName(x.subjectName().trim());m.setMarks(x.marks());r.getSubjects().add(m);}return toResponse(results.save(r));}
 public List<ResultResponse> list(String roll){return results.findByStudentIdOrderByCreatedAtDesc(student(roll).getId()).stream().map(this::toResponse).toList();}
 public ResultResponse get(String roll,Long id){Result r=results.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Result not found"));if(!r.getStudent().getRollNumber().equals(roll))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Result not found");return toResponse(r);}
 public void delete(String roll,Long id){Result r=results.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Result not found"));if(!r.getStudent().getRollNumber().equals(roll))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Result not found");results.delete(r);}
 private Student student(String roll){return students.findByRollNumber(roll).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));}
 private ResultResponse toResponse(Result r){List<SubjectResponse> subs=r.getSubjects().stream().map(x->new SubjectResponse(x.getSubjectName(),x.getMarks())).toList();SubjectResponse high=subs.stream().max(Comparator.comparingInt(SubjectResponse::marks)).orElse(null),low=subs.stream().min(Comparator.comparingInt(SubjectResponse::marks)).orElse(null);long above=subs.stream().filter(x->x.marks()>80).count(),below=subs.stream().filter(x->x.marks()<50).count();return new ResultResponse(r.getId(),r.getStudent().getName(),r.getStudent().getRollNumber(),r.getTotalMarks(),r.getMaximumMarks(),r.getAveragePercentage(),r.getGrade(),calc.status(r.getAveragePercentage()),r.getFeedback(),high==null?"":high.subjectName()+" - "+high.marks(),low==null?"":low.subjectName()+" - "+low.marks(),above,below,subs,r.getCreatedAt());}
}